class MinStack:
    """A stack that reports its smallest value."""

    def __init__(self):
        self._items = []
        self._min_stack = []

    def push(self, value):
        self._items.append(value)
        if not self._min_stack or value < self._min_stack[-1]:
            self._min_stack.append(value)
        else:
            self._min_stack.append(self._min_stack[-1])

    def pop(self):
        self._min_stack.pop()
        return self._items.pop()

    def top(self):
        return self._items[-1]

    def get_min(self):
        if not self._min_stack:
            raise ValueError("get_min() called on empty stack")
        return self._min_stack[-1]

    def __len__(self):
        return len(self._items)
